'use client';
import cl from "clsx/lite";
import { forwardRef } from "react";
import { jsx } from "react/jsx-runtime";
//#region src/components/file-upload/file-upload.tsx
/**
* FileUpload component to present a file upload area.
*
* @example
* <Field>
*  <Label>Upload file</Label>
*  <FileUpload>
*    <CloudUpIcon aria-hidden='true' />
*    <Field.Description>Drop file here</Field.Description>
*    <Field.Description>
*      File must be in csv format and less than 2MB
*    </Field.Description>
*    <Button asChild data-variant='secondary'>
*      <span>Upload file</span>
*    </Button>
*    <input type="file" />
*  </FileUpload>
* </Field>
*/
const FileUpload = forwardRef(function FileUpload({ className, ...rest }, ref) {
	return /* @__PURE__ */ jsx("div", {
		ref,
		className: cl("ds-file-upload", className),
		...rest
	});
});
//#endregion
export { FileUpload };
